/// <summary>
/// Builds the deep trees for <see cref="DeepTreeTests"/>. Deterministic: a fixed xorshift RNG picks the
/// per-node styles, so the same scenario name always yields the same tree.
/// </summary>
public static class DeepTreeFixtures
{
	public const int Depth = 30;

	public static readonly string[] Scenarios =
	{
		"text", "percent", "minmax", "automargins", "wrapgap", "scroll",
		"everything", "everything_unconstrained", "everything_rtl", "everything_pixelgrid", "growchain",
	};

	[Flags]
	private enum Features
	{
		None = 0,
		Percent = 1,
		MinMax = 2,
		AutoMargins = 4,
		WrapGap = 8,
		Scroll = 16,
		Baseline = 32,
		All = Percent | MinMax | AutoMargins | WrapGap | Scroll | Baseline,
	}

	private sealed class Rng
	{
		private ulong _s;
		public Rng( ulong seed ) { _s = seed * 0x9E3779B97F4A7C15UL + 1; }
		public ulong Next() { _s ^= _s << 13; _s ^= _s >> 7; _s ^= _s << 17; return _s; }
		public int Range( int minInclusive, int maxInclusive ) => minInclusive + (int)(Next() % (ulong)(maxInclusive - minInclusive + 1));
		public bool Chance( int percent ) => Range( 0, 99 ) < percent;
	}

	/// <summary>
	/// A text-like measure function: <see cref="LayoutNode.Context"/> is the character count, characters are
	/// 7 x 14 and text wraps to the available width (a "word" is 4 characters for min-content).
	/// </summary>
	internal static LayoutSize MeasureText( LayoutNode node, float width, MeasureMode widthMode, float height, MeasureMode heightMode )
	{
		var chars = (int)node.Context;
		const float charWidth = 7f;
		const float lineHeight = 14f;
		var contentWidth = chars * charWidth;

		float measuredWidth;
		switch ( widthMode )
		{
			case MeasureMode.Exactly: measuredWidth = width; break;
			case MeasureMode.AtMost: measuredWidth = MathF.Min( contentWidth, width ); break;
			case MeasureMode.MinContent: measuredWidth = MathF.Min( contentWidth, 4 * charWidth ); break;
			default: measuredWidth = contentWidth; break;
		}

		var charsPerLine = MathF.Max( 1f, MathF.Floor( measuredWidth / charWidth ) );
		var lines = MathF.Ceiling( chars / charsPerLine );
		var contentHeight = lines * lineHeight;

		float measuredHeight;
		switch ( heightMode )
		{
			case MeasureMode.Exactly: measuredHeight = height; break;
			case MeasureMode.AtMost: measuredHeight = MathF.Min( contentHeight, height ); break;
			default: measuredHeight = contentHeight; break;
		}

		return new LayoutSize( measuredWidth, measuredHeight );
	}

	/// <summary>FNV-1a of the scenario name; string.GetHashCode is randomised per process.</summary>
	private static ulong Seed( string scenario )
	{
		ulong hash = 14695981039346656037UL;
		foreach ( var c in scenario ) hash = (hash ^ c) * 1099511628211UL;
		return hash;
	}

	private static float TextBaseline( LayoutNode node, float width, float height ) => MathF.Min( height, 11f );

	private static LayoutNode Text( Rng rng, List<LayoutNode> all, bool baseline )
	{
		var node = new LayoutNode { Context = rng.Range( 1, 40 ), MeasureFunc = MeasureText };
		if ( baseline ) node.BaselineFunc = TextBaseline;
		all.Add( node );
		return node;
	}

	private static LayoutNode Box( Rng rng, List<LayoutNode> all )
	{
		var node = new LayoutNode();
		node.Style.Width = StyleLength.Points( rng.Range( 5, 60 ) );
		node.Style.Height = StyleLength.Points( rng.Range( 5, 40 ) );
		all.Add( node );
		return node;
	}

	private static void ApplyFeatures( LayoutStyle style, Features features, Rng rng, bool isRow, int depth )
	{
		if ( (features & Features.Percent) != 0 )
		{
			if ( depth % 3 == 1 ) style.Width = StyleLength.Percent( rng.Range( 40, 95 ) );
			if ( depth % 4 == 2 ) style.Height = StyleLength.Percent( rng.Range( 30, 90 ) );
			if ( rng.Chance( 30 ) ) style.SetPadding( Edge.Horizontal, StyleLength.Percent( rng.Range( 1, 4 ) ) );
			if ( rng.Chance( 30 ) ) style.SetMargin( Edge.Left, StyleLength.Percent( rng.Range( 1, 3 ) ) );
		}

		if ( (features & Features.MinMax) != 0 )
		{
			switch ( rng.Range( 0, 5 ) )
			{
				case 0: style.MinWidth = StyleLength.Points( rng.Range( 40, 200 ) ); break;
				case 1: style.MaxWidth = StyleLength.Points( rng.Range( 120, 600 ) ); break;
				case 2: style.MinHeight = StyleLength.Points( rng.Range( 20, 80 ) ); break;
				case 3: style.MaxHeight = StyleLength.Points( rng.Range( 60, 400 ) ); break;
				case 4: style.MaxWidth = StyleLength.Percent( rng.Range( 50, 90 ) ); break;
			}
		}

		if ( (features & Features.AutoMargins) != 0 )
		{
			switch ( rng.Range( 0, 4 ) )
			{
				case 0: style.SetMargin( isRow ? Edge.Left : Edge.Top, StyleLength.Auto ); break;
				case 1: style.SetMargin( isRow ? Edge.Top : Edge.Left, StyleLength.Auto ); break;
				case 2: style.JustifyContent = (Justify)rng.Range( 0, 5 ); break;
				case 3: style.AlignItems = (Align)rng.Range( 1, 4 ); break;
			}
		}

		if ( (features & Features.WrapGap) != 0 && rng.Chance( 35 ) )
		{
			style.FlexWrap = rng.Chance( 80 ) ? Wrap.Wrap : Wrap.WrapReverse;
			style.SetGap( Gutter.All, StyleLength.Points( rng.Range( 1, 6 ) ) );
			if ( rng.Chance( 50 ) ) style.AlignContent = (Align)rng.Range( 1, 8 );
		}

		if ( (features & Features.Scroll) != 0 && rng.Chance( 25 ) )
		{
			style.Overflow = rng.Chance( 50 ) ? Overflow.Scroll : Overflow.Hidden;
		}

		if ( (features & Features.Baseline) != 0 && isRow && rng.Chance( 20 ) )
		{
			style.AlignItems = Align.Baseline;
		}
	}

	private static LayoutNode Build( string scenario, List<LayoutNode> all, out LayoutNode deepLeaf, out float rootWidth, out float rootHeight, out Direction direction )
	{
		var features = scenario switch
		{
			"text" => Features.None,
			"percent" => Features.Percent,
			"minmax" => Features.MinMax,
			"automargins" => Features.AutoMargins,
			"wrapgap" => Features.WrapGap,
			"scroll" => Features.Scroll,
			"growchain" => Features.None,
			_ => Features.All,
		};

		rootWidth = scenario == "everything_unconstrained" ? float.NaN : 900f;
		rootHeight = scenario == "everything_unconstrained" ? float.NaN : 700f;
		direction = scenario == "everything_rtl" ? Direction.RTL : Direction.LTR;

		var rng = new Rng( Seed( scenario ) );
		var growChain = scenario == "growchain";

		var root = new LayoutNode();
		root.Style.FlexDirection = FlexDirection.Column;
		root.Style.SetPadding( Edge.All, StyleLength.Points( 4 ) );
		all.Add( root );

		var parent = root;
		deepLeaf = null;
		for ( int depth = 0; depth < Depth; depth++ )
		{
			var isRow = depth % 2 == 0;
			var container = new LayoutNode();
			var style = container.Style;
			style.FlexDirection = isRow ? FlexDirection.Row : FlexDirection.Column;
			if ( growChain )
			{
				// Every level flex-grows and shrinks, the shape of the benchmark's super_deep tree.
				style.FlexGrow = 1;
				style.SetMargin( Edge.All, StyleLength.Points( 10 ) );
			}
			else
			{
				style.SetMargin( Edge.All, StyleLength.Points( rng.Range( 0, 6 ) ) );
				style.SetPadding( Edge.All, StyleLength.Points( rng.Range( 0, 5 ) ) );
				if ( rng.Chance( 20 ) ) style.SetBorder( Edge.All, StyleLength.Points( 1 ) );
				if ( rng.Chance( 40 ) ) style.FlexGrow = 1;
				if ( rng.Chance( 20 ) ) style.FlexShrink = 0;
				if ( rng.Chance( 15 ) ) style.AlignSelf = (Align)rng.Range( 1, 4 );
				ApplyFeatures( style, features, rng, !isRow, depth );
			}

			// Siblings around the nested container: text leaves, the odd fixed box, and occasionally a
			// shallow auto-sized sub-container with its own text.
			var siblingsBefore = rng.Range( 0, 2 );
			var siblingsAfter = rng.Range( 0, 2 );
			for ( int i = 0; i < siblingsBefore; i++ ) AddSibling( parent, rng, all, features, isRow, depth );
			parent.AddChild( container );
			all.Add( container );
			for ( int i = 0; i < siblingsAfter; i++ ) AddSibling( parent, rng, all, features, isRow, depth );

			parent = container;
		}

		// The innermost container gets a few leaves; the first one is what the incremental pass dirties.
		deepLeaf = Text( rng, all, false );
		parent.AddChild( deepLeaf );
		parent.AddChild( Box( rng, all ) );
		parent.AddChild( Text( rng, all, false ) );

		return root;
	}

	private static void AddSibling( LayoutNode parent, Rng rng, List<LayoutNode> all, Features features, bool parentIsRow, int depth )
	{
		var roll = rng.Range( 0, 9 );
		LayoutNode sibling;
		if ( roll < 6 )
		{
			sibling = Text( rng, all, (features & Features.Baseline) != 0 && rng.Chance( 50 ) );
			if ( rng.Chance( 30 ) ) sibling.Style.FlexGrow = 1;
			if ( rng.Chance( 30 ) ) sibling.Style.FlexShrink = 0;
			ApplyFeatures( sibling.Style, features & (Features.Percent | Features.MinMax | Features.AutoMargins), rng, parentIsRow, depth );
		}
		else if ( roll < 8 )
		{
			sibling = Box( rng, all );
			if ( rng.Chance( 50 ) ) sibling.Style.FlexGrow = 1;
		}
		else
		{
			// An auto-sized sub-container with two text children, so the parent measures a container that
			// is not on the deep chain.
			sibling = new LayoutNode();
			sibling.Style.FlexDirection = parentIsRow ? FlexDirection.Column : FlexDirection.Row;
			sibling.Style.SetPadding( Edge.All, StyleLength.Points( rng.Range( 0, 3 ) ) );
			if ( rng.Chance( 50 ) ) sibling.Style.FlexGrow = 1;
			ApplyFeatures( sibling.Style, features, rng, !parentIsRow, depth );
			all.Add( sibling );
			sibling.AddChild( Text( rng, all, false ) );
			sibling.AddChild( Text( rng, all, false ) );
		}

		parent.AddChild( sibling );
	}

	/// <summary>
	/// Builds the scenario, lays it out three times (initial, after dirtying the deepest text leaf, after
	/// changing the root's available size) and returns the rects of every node after each pass, one pass per
	/// line, as "left,top,width,height" entries in document order.
	/// </summary>
	public static string Dump( string scenario )
	{
		var all = new List<LayoutNode>();
		var root = Build( scenario, all, out var deepLeaf, out var rootWidth, out var rootHeight, out var direction );

		var sb = new StringBuilder();

		root.CalculateLayout( rootWidth, rootHeight, direction );
		AppendRects( sb, all );

		// Incremental: change the deepest text and re-lay out. Only the path to the root is dirty.
		deepLeaf.Context = (int)deepLeaf.Context + 23;
		deepLeaf.MarkDirty();
		root.CalculateLayout( rootWidth, rootHeight, direction );
		sb.Append( '\n' );
		AppendRects( sb, all );

		// The root's constraints change; nothing is dirty, so every node's cache is consulted.
		root.CalculateLayout( float.IsNaN( rootWidth ) ? 640f : rootWidth - 137f, float.NaN, direction );
		sb.Append( '\n' );
		AppendRects( sb, all );

		return sb.ToString();
	}

	/// <summary>
	/// Produces the same three states as <see cref="Dump"/>, rebuilding the tree before each state so no
	/// cached measurement can influence the expected result.
	/// </summary>
	public static string DumpFresh( string scenario )
	{
		var sb = new StringBuilder();
		AppendFreshPass( sb, scenario, false, false );
		sb.Append( '\n' );
		AppendFreshPass( sb, scenario, true, false );
		sb.Append( '\n' );
		AppendFreshPass( sb, scenario, true, true );
		return sb.ToString();
	}

	private static void AppendFreshPass( StringBuilder sb, string scenario, bool mutateLeaf, bool resizeRoot )
	{
		var all = new List<LayoutNode>();
		var root = Build( scenario, all, out var deepLeaf, out var rootWidth, out var rootHeight, out var direction );
		if ( mutateLeaf ) deepLeaf.Context = (int)deepLeaf.Context + 23;
		if ( resizeRoot ) rootWidth = float.IsNaN( rootWidth ) ? 640f : rootWidth - 137f;
		if ( resizeRoot ) rootHeight = float.NaN;
		root.CalculateLayout( rootWidth, rootHeight, direction );
		AppendRects( sb, all );
	}

	private static void AppendRects( StringBuilder sb, List<LayoutNode> all )
	{
		var ci = CultureInfo.InvariantCulture;
		for ( int i = 0; i < all.Count; i++ )
		{
			if ( i > 0 ) sb.Append( ';' );
			var n = all[i];
			sb.Append( n.LayoutLeft.ToString( "R", ci ) ).Append( ',' ).Append( n.LayoutTop.ToString( "R", ci ) ).Append( ',' )
				.Append( n.LayoutWidth.ToString( "R", ci ) ).Append( ',' ).Append( n.LayoutHeight.ToString( "R", ci ) );
		}
	}
}
